alter table public.record_relief_evaluations add column if not exists engine_version text;alter table public.record_relief_evaluations add column if not exists next_reevaluate_at timestamptz;create index if not exists record_relief_evaluations_reevaluate_idx on public.record_relief_evaluations(next_reevaluate_at) where superseded=false;create table if not exists public.record_relief_law_change_reviews(id uuid primary key default gen_random_uuid(),jurisdiction_code text not null,status text not null default 'detected' check(status in('detected','reviewing','approved','rejected','published')),old_rule_version integer,proposed_rule_version integer,authority_url text not null,effective_on date,summary text not null,affected_case_count integer not null default 0,detected_at timestamptz not null default now(),reviewed_at timestamptz,published_at timestamptz,reviewed_by uuid references auth.users(id));alter table public.record_relief_law_change_reviews enable row level security;revoke all on table public.record_relief_law_change_reviews from anon,authenticated;grant select,insert,update,delete on table public.record_relief_law_change_reviews to service_role;create or replace function public.record_relief_notify_due() returns integer language plpgsql security definer set search_path=public as $$declare n integer:=0;begin insert into public.user_notifications(user_id,category,title,body,route,metadata,dedupe_key,entity_type,entity_id) select distinct e.user_id,'record_relief','Record relief date reached','A waiting-period date FairPath was tracking has arrived. Re-check the case because law and case facts can change.','/record-relief/case/'||e.case_id,jsonb_build_object('case_id',e.case_id,'eligibility_date',e.eligibility_date),'rr:eligible:'||e.case_id||':'||e.eligibility_date,'record_relief_case',e.case_id from public.record_relief_evaluations e where not e.superseded and e.eligibility_date is not null and e.eligibility_date<=current_date on conflict(user_id,dedupe_key) where dedupe_key is not null do nothing;get diagnostics n=row_count;return n;end$$;revoke all on function public.record_relief_notify_due() from public,anon,authenticated;grant execute on function public.record_relief_notify_due() to service_role;